typedef struct { int32_t from, until; } effectivity;   /* yyyymmdd; until == 0 -> open */

static int eff_contains(effectivity p, int32_t day) {
    return day >= p.from && (p.until == 0 || day < p.until);   /* [from, until) */
}

static int eff_overlaps(effectivity a, effectivity b) {
    return (b.until == 0 || a.from < b.until) && (a.until == 0 || b.from < a.until);
}

